using J=cubed_sphere::Jet;using Original=h::TransitionBackgroundJet;using Orth=h::TransitionOrthogonalBackgroundJet;
Real Scale(const Grid&g,size_t p){Real maxrow=0;for(int A=0;A<3;++A){Real sum=0;for(int a=0;a<3;++a)sum+=g.geometry[p].J[A][a]*g.geometry[p].J[A][a];maxrow=std::max(maxrow,std::sqrt(sum));}return 1/(g.n*maxrow);}
J SinJet(const J&a){J b(std::sin(a.f));for(int i=0;i<3;++i){b.d[i]=std::cos(a.f)*a.d[i];for(int j=0;j<3;++j)b.h[i][j]=std::cos(a.f)*a.h[i][j]-std::sin(a.f)*a.d[i]*a.d[j];}return b;}
J Delta(int mode,const Point&x){J y[3];for(int a=0;a<3;++a)y[a]=J::Variable(x[a],a);if(mode==0)return J(1);if(mode==1)return y[0]+J(.3)*y[1]-J(.7)*y[2]+y[0]*y[0]+J(.7)*y[0]*y[1]+J(2)*y[2]*y[2];if(mode==2||mode==3)return J(0);if(mode==4)return J(.001)*SinJet(J(3)*y[0])*SinJet(J(2)*y[1])+J(.001)*y[2]*y[2]*y[2];if(mode==5)return J(.001)*y[0]*y[1]/(y[0]*y[0]+y[1]*y[1]+y[2]*y[2]);if(mode==6)return J(.1)*SinJet(J(12)*y[0]+J(7)*y[1]-J(5)*y[2]);return J(.2)*cubed_sphere::Log(cubed_sphere::Power(y[0]*y[0]+y[1]*y[1]+y[2]*y[2],.5)+J(.17));}
Real Coefficient(int mode){return mode<2?0:(mode==3?.7:1);}
std::array<Real,24> PhysicalQuantities(U u,const Point&x){const auto omega=h::CompositeOmegaAt(x.data(),u);const auto c=h::EvolvedConstraints(u,omega);const auto p=h::ConformalRHS(u,omega,Real(4),Real(-.99),true);h::Z4cRHS<Real> rhs{};if(!c.valid||!h::AssembleInterior(p,omega.omega,rhs))throw std::runtime_error("invalid independent initial source");std::array<Real,24> out{};out[0]=c.hamiltonian;out[1]=std::sqrt(c.momentum_conformal_norm2);out[2]=rhs.chi;out[3]=rhs.trace;out[4]=rhs.theta;out[5]=h::WormholeLapseRate(x.data(),u);for(int t=0;t<6;++t){out[6+t]=rhs.metric[Engine::tensor_i[t]][Engine::tensor_j[t]];out[12+t]=rhs.a[Engine::tensor_i[t]][Engine::tensor_j[t]];}for(int i=0;i<3;++i){out[18+i]=rhs.lambda[i];out[21+i]=.005/.02*h::ReferenceTelegraphSupport(Radius(x.data()),.8,.24).value*u.alpha.d[i];}for(Real v:out)if(!std::isfinite(v))throw std::runtime_error("nonfinite full initial source");return out;}

struct Audit {Real value=0,gradient=0,hessian=0,coefficient=0;std::vector<std::array<Real,10>> weights;};
template<class Plan>Audit FunctionalAudit(const Plan&plan,int count,Real h,const h::PuncturePosition&point){Audit a;Real g[3]{},dd[3][3]{};for(int i=0;i<count;++i){V impulse(count,0);impulse[i]=1;typename Plan::Result r;if(!plan.Evaluate(impulse,point,r))throw std::runtime_error("basis impulse");std::array<Real,10>w{};w[0]=r.fitted_value;a.value+=std::abs(w[0]);a.coefficient+=std::abs(r.enrichment_coefficient);for(int d=0;d<3;++d){w[1+d]=h*r.gradient[d];g[d]+=std::abs(w[1+d]);}int row=4;for(int d=0;d<3;++d)for(int e=d;e<3;++e,++row){w[row]=h*h*r.hessian[d][e];dd[d][e]+=std::abs(w[row]);}a.weights.push_back(w);}for(int d=0;d<3;++d){a.gradient=std::max(a.gradient,g[d]);for(int e=d;e<3;++e)a.hessian=std::max(a.hessian,dd[d][e]);}return a;}
template<class Plan>S Evaluate(const Plan&plan,const V&v,Real value,const h::PuncturePosition&p,Real &coefficient){typename Plan::Result r;if(!plan.Evaluate(v,p,r))throw std::runtime_error("basis field");S q{};q.value=value;coefficient=r.enrichment_coefficient;for(int a=0;a<3;++a){q.d[a]=r.gradient[a];for(int b=0;b<3;++b)q.dd[a][b]=r.hessian[a][b];}return q;}
bool Safe(const Audit&a,Real reproduction){return a.value<=16&&a.gradient<=32&&a.hessian<=64&&a.coefficient<=10000&&reproduction<=1e-10;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int status=0;try{if(argc!=3)throw std::runtime_error("initial.dat exact.dat");auto grid=MakeGrid();const auto initial=ReadInitial(argv[1],grid);const auto exact=ReadExact(argv[2]);h::PuncturePosition point;std::cout<<std::setprecision(17)<<"{\"phase\":\"precision\",\"sizeof_double\":"<<sizeof(double)<<",\"double_digits\":"<<std::numeric_limits<double>::digits<<",\"sizeof_long_double\":"<<sizeof(long double)<<",\"long_double_digits\":"<<std::numeric_limits<long double>::digits<<",\"long_double_is_extended\":"<<(std::numeric_limits<long double>::digits>std::numeric_limits<double>::digits)<<"}\n";
 const char*names[]={"constant","Cartesian_P2","initial_B","scaled_B_07","small_smooth","angular","strong_nonspherical","changed_radial"};int ready=0,rejected=0,compared=0;Real maxweights=0,maxsources=0,maxnoise=0;
 for(size_t p:{size_t(0),size_t(120),size_t(126),size_t(1218)}){const auto&x=grid.geometry[p].x;const Point at{x[0],x[1],x[2]};const Real h=Scale(grid,p);std::vector<std::pair<Real,size_t>>near;for(size_t q=0;q<grid.active.size();++q){Real d=0;for(int a=0;a<3;++a)d+=std::pow(grid.geometry[q].x[a]-x[a],2);near.push_back({d,q});}std::partial_sort(near.begin(),near.begin()+256,near.end());
 for(int field=0;field<2;++field)for(int count:{125,175,256}){std::vector<Original::Point>nodes;V bg;for(int i=0;i<count;++i){const size_t q=near[i].second;const auto&y=grid.geometry[q].x;nodes.push_back({y[0],y[1],y[2]});bg.push_back(field==0?std::log(initial[q].chi):std::log(initial[q].alpha/((1+initial[q].r*initial[q].r)/2)));}const S background=StoredExact(x,exact.at({0,p}),field);Original original;Original::Options oo;oo.maximum_condition=1e8;oo.maximum_scaled_weight_l1=1e6;const bool original_built=original.Build(at,nodes,bg,background,h,point,oo);Audit original_audit;if(original_built)original_audit=FunctionalAudit(original,count,h,point);h::TransitionBackgroundProjection projection;const bool projected=projection.Build(at,nodes,bg,background,h);Orth orth;Orth::Options options;options.maximum_condition=1e8;options.maximum_scaled_weight_l1=1e6;const bool built=projected&&orth.Build(at,nodes,projection.residual,projection.query,h,point,options);Audit audit;if(built)audit=FunctionalAudit(orth,count,h,point);const bool valid=built&&Safe(audit,orth.diagnostics().reproduction);std::cout<<"{\"phase\":\"plan\",\"point\":"<<p<<",\"field\":\""<<(field==0?"chi":"alpha")<<"\",\"donors\":"<<count<<",\"original_status\":\""<<original.diagnostics().status<<"\",\"original_rank\":"<<original.diagnostics().rank<<",\"original_condition\":"<<original.diagnostics().condition<<",\"original_reproduction\":"<<original.diagnostics().reproduction<<",\"original_all_gates\":"<<(original_built&&Safe(original_audit,original.diagnostics().reproduction))<<",\"P5_status\":\""<<projection.status<<"\",\"P5_rank\":"<<projection.rank<<",\"P5_condition\":"<<projection.condition<<",\"background_residual_norm\":"<<projection.residual_norm<<",\"relative_residual\":"<<projection.relative_residual<<",\"preconditioned_status\":\""<<orth.diagnostics().status<<"\",\"preconditioned_rank\":"<<orth.diagnostics().rank<<",\"preconditioned_condition\":"<<orth.diagnostics().condition<<",\"preconditioned_reproduction\":"<<orth.diagnostics().reproduction<<",\"value_l1\":"<<audit.value<<",\"gradient_l1\":"<<audit.gradient<<",\"hessian_l1\":"<<audit.hessian<<",\"coefficient_l1\":"<<audit.coefficient<<",\"all_gates\":"<<valid<<"}\n";
  if(built&&original_built){Real change=0;for(int i=0;i<count;++i)for(int f=0;f<10;++f)change=std::max(change,std::abs(audit.weights[i][f]-original_audit.weights[i][f]));maxweights=std::max(maxweights,change);++compared;std::cout<<"{\"phase\":\"physical_weights\",\"point\":"<<p<<",\"field\":\""<<(field==0?"chi":"alpha")<<"\",\"donors\":"<<count<<",\"maximum_scaled_difference\":"<<change<<",\"within_1e_9\":"<<(change<=1e-9)<<"}\n";}
  if(!valid){++rejected;continue;}++ready;
  for(int mode=0;mode<8;++mode){const Real c=Coefficient(mode);const auto delta=Delta(mode,at);V values;for(int i=0;i<count;++i)values.push_back(c*bg[i]+Delta(mode,nodes[i]).f);S truth{};truth.value=c*background.value+delta.f;for(int a=0;a<3;++a){truth.d[a]=c*background.d[a]+delta.d[a];for(int b=0;b<3;++b)truth.dd[a][b]=c*background.dd[a][b]+delta.h[a][b];}Real coef;const auto fit=Evaluate(orth,values,truth.value,point,coef);Real gd=0,hd=0;for(int a=0;a<3;++a){gd=std::max(gd,std::abs(fit.d[a]-truth.d[a]));for(int b=0;b<3;++b)hd=std::max(hd,std::abs(fit.dd[a][b]-truth.dd[a][b]));}S physical{},analytic{};if(Chart(x,field).Reconstruct(fit,physical)!=h::PositiveFieldStatus::valid||Chart(x,field).Reconstruct(truth,analytic)!=h::PositiveFieldStatus::valid)throw std::runtime_error("orth physical jet");auto u=Analytic(at,exact.at({0,p})),ue=u;if(field==0){u.chi=physical;ue.chi=analytic;}else{u.alpha=physical;ue.alpha=analytic;}const auto actual=PhysicalQuantities(u,at),expected=PhysicalQuantities(ue,at);Real sourceerror=0;for(int i=2;i<24;++i)sourceerror=std::max(sourceerror,std::abs(actual[i]-expected[i]));Real oldchange=0;if(original_built){Real oldcoef;const auto q=Evaluate(original,values,truth.value,point,oldcoef);S oldphysical{};if(Chart(x,field).Reconstruct(q,oldphysical)!=h::PositiveFieldStatus::valid)throw std::runtime_error("original matched jet");auto old=u;if(field==0)old.chi=oldphysical;else old.alpha=oldphysical;const auto oldsource=PhysicalQuantities(old,at);for(int i=0;i<24;++i)oldchange=std::max(oldchange,std::abs(actual[i]-oldsource[i]));maxsources=std::max(maxsources,oldchange);}V noisy=values;for(int i=0;i<count;++i)noisy[i]+=1e-12*(std::sin(1.7*i)+std::cos(.9*i))/2;Real nc;const auto noise=Evaluate(orth,noisy,truth.value,point,nc);Real ns=0;for(int a=0;a<3;++a){ns=std::max(ns,h*std::abs(noise.d[a]-fit.d[a]));for(int b=0;b<3;++b)ns=std::max(ns,h*h*std::abs(noise.dd[a][b]-fit.dd[a][b]));}if(ns>std::max(audit.gradient,audit.hessian)*1e-12+2e-13)throw std::runtime_error("orth noise bound");maxnoise=std::max(maxnoise,ns);std::cout<<"{\"phase\":\"field\",\"point\":"<<p<<",\"field\":\""<<(field==0?"chi":"alpha")<<"\",\"donors\":"<<count<<",\"case\":\""<<names[mode]<<"\",\"coefficient_original_units\":"<<coef/projection.residual_norm<<",\"gradient_error\":"<<gd<<",\"hessian_error\":"<<hd<<",\"H_error\":"<<actual[0]-expected[0]<<",\"full_source_error_max\":"<<sourceerror<<",\"original_source_change_max\":"<<oldchange<<",\"scaled_noise\":"<<ns<<",\"active_value_changed\":false}\n";
  }
 }
 }
 std::cout<<"{\"phase\":\"summary\",\"queries\":4,\"ready\":"<<ready<<",\"rejected\":"<<rejected<<",\"compared\":"<<compared<<",\"physical_weight_change_max\":"<<maxweights<<",\"source_change_max\":"<<maxsources<<",\"scaled_noise_max\":"<<maxnoise<<",\"all57columns_retained\":true,\"physical_caps_unchanged\":true,\"reproduction_gate_unchanged\":true,\"production_adopted\":false}\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
